<?php defined('ABSPATH') || exit; if (!valon_dashboard_owner()) exit;
$groups = ['needs-valon' => 'Needs Valon', 'in-progress' => 'In progress', 'blocked' => 'Blocked', 'done' => 'Done'];
$items = array_filter($inventory['items'] ?? [], fn($item) => is_array($item) && isset($groups[$item['status'] ?? '']));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Your workspace · Valon Asani</title><link rel="stylesheet" href="<?php echo esc_url(get_template_directory_uri() . '/assets/dashboard.css'); ?>"></head><body>
<header><a class="brand" href="<?php echo esc_url(home_url('/')); ?>">VALON ASANI</a><span>Private workspace</span><a href="<?php echo esc_url(wp_logout_url(home_url('/'))); ?>">Sign out</a></header>
<main><p class="eyebrow">YOUR WORK, IN ONE PLACE</p><h1>Where things stand.</h1><p class="intro">Decisions first. Progress, blockers and finished work below.</p><p class="note">A dated review of our work, not a live integration. Each source keeps its own access permissions.</p>
<nav aria-label="Work status"><?php foreach ($groups as $key => $label): $count = count(array_filter($items, fn($i) => $i['status'] === $key)); ?><a href="#<?php echo esc_attr($key); ?>"><?php echo esc_html($label); ?> <strong><?php echo (int) $count; ?></strong></a><?php endforeach; ?><a href="#weekly-tasks">Weekly SEO tasks</a></nav>
<section aria-labelledby="overview"><h2 id="overview">At a glance</h2><div class="overview"><?php foreach (($inventory['overview_ids'] ?? []) as $id): foreach ($items as $item): if (($item['id'] ?? '') !== $id) continue; ?><a href="#item-<?php echo esc_attr($id); ?>"><span class="area"><?php echo esc_html($item['area']); ?></span><strong><?php echo esc_html($item['title']); ?></strong><span><?php echo esc_html($groups[$item['status']]); ?></span></a><?php endforeach; endforeach; ?></div></section>
<?php if (!$items): ?><p class="empty">Your verified inventory has not been loaded yet. No project status is assumed.</p><?php endif; ?>
<?php foreach ($groups as $key => $label): ?><section id="<?php echo esc_attr($key); ?>"><h2><?php echo esc_html($label); ?></h2><?php $rows = array_filter($items, fn($i) => $i['status'] === $key); if (!$rows): ?><p class="muted">No items recorded in this section.</p><?php endif; foreach ($rows as $item): ?>
<details id="item-<?php echo esc_attr($item['id'] ?? ''); ?>"><summary><span class="area"><?php echo esc_html($item['area'] ?? 'Work'); ?></span><span class="title"><?php echo esc_html($item['title'] ?? 'Untitled'); ?><small><?php echo esc_html($item['summary'] ?? ''); ?></small></span><span class="expand" aria-hidden="true">+</span></summary><div class="detail"><p><?php echo nl2br(esc_html($item['detail'] ?? '')); ?></p><?php if (!empty($item['next'])): ?><p><strong>Next step:</strong> <?php echo esc_html($item['next']); ?></p><?php endif; ?><p class="muted">Last verified: <?php echo esc_html($item['verified'] ?? 'Not verified'); ?><?php if (!empty($item['as_of'])): ?> · Evidence as of <?php echo esc_html($item['as_of']); ?><?php endif; ?></p><ul class="sources"><?php foreach (($item['sources'] ?? []) as $source): $url = $source['url'] ?? ''; if (parse_url($url, PHP_URL_SCHEME) !== 'https') continue; ?><li><a href="<?php echo esc_url($url); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html($source['label'] ?? 'Open source'); ?> ↗</a></li><?php endforeach; ?></ul></div></details>
<?php endforeach; ?></section><?php endforeach; ?>
<section id="weekly-tasks"><h2>Weekly SEO tasks</h2><p class="muted">Evidence-backed proposals. Repeated findings reuse the same task. No automatic article rewrites or outreach.</p>
<?php if (empty($inventory['tasks'])): ?><p>No improvement tasks recorded yet.</p><?php endif; foreach (($inventory['tasks'] ?? []) as $task): ?><details><summary><span class="area"><?php echo esc_html($task['id'] ?? ''); ?></span><span class="title"><?php echo esc_html($task['title'] ?? ''); ?><small><?php echo esc_html($task['status'] ?? 'proposed'); ?> · Last verified <?php echo esc_html($task['verified'] ?? 'Not verified'); ?></small></span><span class="expand" aria-hidden="true">+</span></summary><div class="detail"><?php foreach (['evidence'=>'Evidence','proposed_change'=>'Proposed change','success_criterion'=>'Success criterion','evaluation_period'=>'Evaluation period'] as $field=>$label): ?><p><strong><?php echo esc_html($label); ?>:</strong> <?php echo esc_html($task[$field] ?? ''); ?></p><?php endforeach; if (parse_url($task['url'] ?? '', PHP_URL_SCHEME)==='https'): ?><a href="<?php echo esc_url($task['url']); ?>" rel="noopener noreferrer" target="_blank">Affected article ↗</a><?php endif; ?></div></details><?php endforeach; ?></section>
<footer>Owner-only · Source links do not grant access · No background account connections</footer></main></body></html>
